sys_script_client.script:
function onSubmit() {
	if (!g_form.isNewRecord()) return true;
    var manager = g_form.getValue('branch_manager');
    var maxCapacity = parseInt(g_form.getValue('maximum_capacity'), 10); 
    var totalCapacity = parseInt(g_form.getValue('total_capacity'), 10); 

    // Preenchendo o campo de controle pra não ter que fazer isso no cadastro e ter um campo não solicitado no form
    if (isNaN(totalCapacity) || totalCapacity === 0) {
        g_form.setValue('total_capacity', maxCapacity);
        totalCapacity = maxCapacity;
    }

    // Verificação pra subtrair apenas uma vez
    if (totalCapacity - maxCapacity >= 1) {
        return true;
    }

    // Mais uma verificação para capacidade max e o campo gerente
    if (manager && !isNaN(maxCapacity) && maxCapacity > 0) {
        g_form.setValue('maximum_capacity', maxCapacity - 1);
    }

    return true;
}
